1	package com.study.app.web;
2	
3	import com.study.app.command.OrderCommandService;
4	import com.study.app.domain.Order;
5	import com.study.app.query.OrderQueryService;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.http.HttpStatus;
8	import org.springframework.web.bind.annotation.*;
9	import org.springframework.web.server.ResponseStatusException;
10	import java.util.*;
11	
12	@RestController
13	public class OrderController {
14	
15	    @Autowired
16	    private OrderCommandService orderCommandService;
17	    @Autowired
18	    private OrderQueryService orderQueryService;
19	
20	    @PostMapping("/orders")
21	    @ResponseStatus(HttpStatus.ACCEPTED)
22	    public Map<String, Object> placeOrder(@RequestBody Map<String, Object> body) {
23	        Object orderIdObj = body.get("orderId");
24	        Object customerIdObj = body.get("customerId");
25	        Object productIdObj = body.get("productId");
26	        Object quantityObj = body.get("quantity");
27	
28	        if (orderIdObj == null || customerIdObj == null || productIdObj == null || quantityObj == null) {
29	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "missing required fields");
30	        }
31	
32	        int quantity;
33	        try {
34	            quantity = ((Number) quantityObj).intValue();
35	        } catch (ClassCastException e) {
36	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "invalid quantity");
37	        }
38	        if (quantity < 1) throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "quantity must be >= 1");
39	
40	        UUID orderId, customerId, productId;
41	        try {
42	            orderId = UUID.fromString(orderIdObj.toString());
43	            customerId = UUID.fromString(customerIdObj.toString());
44	            productId = UUID.fromString(productIdObj.toString());
45	        } catch (IllegalArgumentException e) {
46	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "invalid UUID format");
47	        }
48	
49	        Order order = orderCommandService.placeOrder(orderId, customerId, productId, quantity);
50	        return orderToMap(order);
51	    }
52	
53	    @GetMapping("/orders/{id}")
54	    public Map<String, Object> getOrder(@PathVariable UUID id) {
55	        return orderToMap(orderQueryService.getOrder(id));
56	    }
57	
58	    private Map<String, Object> orderToMap(Order o) {
59	        Map<String, Object> m = new LinkedHashMap<>();
60	        m.put("orderId", o.getOrderId().toString());
61	        m.put("customerId", o.getCustomerId().toString());
62	        m.put("productId", o.getProductId().toString());
63	        m.put("quantity", o.getQuantity());
64	        m.put("status", o.getStatus().name());
65	        if (o.getReason() != null) {
66	            m.put("reason", o.getReason());
67	        }
68	        if (o.getTotal() != null) {
69	            m.put("total", o.getTotal());
70	        }
71	        return m;
72	    }
73	}
