3	import com.study.app.domain.*;
4	import org.springframework.beans.factory.annotation.Autowired;
5	import org.springframework.dao.DataIntegrityViolationException;
6	import org.springframework.http.HttpStatus;
7	import org.springframework.orm.ObjectOptimisticLockingFailureException;
8	import org.springframework.stereotype.Service;
9	import org.springframework.web.server.ResponseStatusException;
10	import java.util.UUID;
11	
12	@Service
13	public class OrderCommandService {
14	
15	    @Autowired
16	    private OrderCreationHelper creationHelper;
17	    @Autowired
18	    private OrderProcessor processor;
19	    @Autowired
20	    private OrderRepository orderRepository;
21	    @Autowired
22	    private ProductRepository productRepository;
23	    @Autowired
24	    private CustomerRepository customerRepository;
25	
26	    public Order placeOrder(UUID orderId, UUID customerId, UUID productId, int quantity) {
27	        if (!productRepository.existsById(productId)) {
28	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "product not found");
29	        }
30	        if (!customerRepository.existsById(customerId)) {
31	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "customer not found");
32	        }
33	
34	        Order order;
35	        try {
36	            order = creationHelper.insert(orderId, customerId, productId, quantity);
37	        } catch (DataIntegrityViolationException e) {
38	            // orderId already exists — idempotent replay
39	            order = creationHelper.findById(orderId);
40	        }
41	
42	        if (order.getStatus() == OrderStatus.PENDING) {
43	            try {
44	                processor.process(orderId);
45	            } catch (ObjectOptimisticLockingFailureException e) {
46	                // another concurrent thread won the processing race — fine
47	            }
48	        }
49	
50	        return orderRepository.findById(orderId).orElseThrow();
51	    }
52	}
