12	
13	@Service
14	public class NotificationService {
15	
16	    @Autowired
17	    private NotificationRepository notificationRepository;
18	
19	    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
20	    @Transactional(propagation = Propagation.REQUIRES_NEW)
21	    public void onOrderDecided(OrderDecidedEvent event) {
22	        try {
23	            notificationRepository.saveAndFlush(
24	                new Notification(event.orderId(), event.customerId(), event.status(), event.reason())
25	            );
26	        } catch (DataIntegrityViolationException e) {
27	            // already notified (idempotent)
28	        }
