1	package com.study.app.command;
2	
3	import com.study.app.domain.*;
4	import org.springframework.beans.factory.annotation.Autowired;
5	import org.springframework.context.ApplicationEventPublisher;
6	import org.springframework.stereotype.Component;
7	import org.springframework.transaction.annotation.Transactional;
8	import java.util.UUID;
9	
10	@Component
11	public class OrderProcessor {
12	
13	    @Autowired
14	    private OrderRepository orderRepository;
15	    @Autowired
16	    private ProductRepository productRepository;
17	    @Autowired
18	    private CustomerRepository customerRepository;
19	    @Autowired
20	    private ApplicationEventPublisher publisher;
21	
22	    @Transactional
23	    public void process(UUID orderId) {
24	        Order order = orderRepository.findById(orderId).orElseThrow();
25	        if (order.getStatus() != OrderStatus.PENDING) {
26	            return;
27	        }
28	
29	        Product product = productRepository.findById(order.getProductId()).orElseThrow();
30	        long total = (long) order.getQuantity() * product.getUnitPrice();
31	
32	        if (productRepository.reserve(order.getProductId(), order.getQuantity()) == 0) {
33	            order.reject("OUT_OF_STOCK");
34	            orderRepository.save(order);
35	            publisher.publishEvent(new OrderDecidedEvent(orderId, order.getCustomerId(), OrderStatus.REJECTED, "OUT_OF_STOCK"));
36	            return;
37	        }
38	
39	        if (customerRepository.charge(order.getCustomerId(), total) == 0) {
40	            productRepository.release(order.getProductId(), order.getQuantity());
41	            order.reject("INSUFFICIENT_FUNDS");
42	            orderRepository.save(order);
43	            publisher.publishEvent(new OrderDecidedEvent(orderId, order.getCustomerId(), OrderStatus.REJECTED, "INSUFFICIENT_FUNDS"));
44	            return;
45	        }
46	
47	        order.confirm(total);
48	        orderRepository.save(order);
49	        publisher.publishEvent(new OrderDecidedEvent(orderId, order.getCustomerId(), OrderStatus.CONFIRMED, null));
50	    }
51	}
